drills.solution:
export function makeCreateOrder(store) {
  const inFlight = new Map();

  const attempt = async (key, body) => {
    const saved = await store.findKey(key);
    if (saved) return saved;
    const order = await store.insertOrder(body);
    await store.saveKey(key, order);
    return order;
  };

  return function createOrder(key, body) {
    const running = inFlight.get(key);
    if (running) return running;
    const work = attempt(key, body).finally(() => inFlight.delete(key));
    inFlight.set(key, work);
    return work;
  };
}

